import React from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { Toaster } from "react-hot-toast";

import { AuthProvider, useAuth } from "./hooks/useAuth";
import DashboardLayout from "./components/layout/DashboardLayout";
import Spinner from "./components/ui/Spinner";

import LoginPage from "./pages/LoginPage";
import RegisterPage from "./pages/RegisterPage";
import DashboardOverview from "./pages/DashboardOverview";
import ProfileHealth from "./pages/ProfileHealth";
import PostureStudio from "./pages/PostureStudio";
import WorkoutEngine from "./pages/WorkoutEngine";
import CoachChat from "./pages/CoachChat";
import ProgressAnalytics from "./pages/ProgressAnalytics";

/** Guards authenticated routes; redirects to /login if no valid session. */
function ProtectedRoute({ children }) {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-base">
        <Spinner size={28} label="Loading your dashboard..." />
      </div>
    );
  }
  if (!user) return <Navigate to="/login" replace />;
  return children;
}

function AppRoutes() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route path="/register" element={<RegisterPage />} />

      <Route
        element={
          <ProtectedRoute>
            <DashboardLayout />
          </ProtectedRoute>
        }
      >
        <Route path="/" element={<DashboardOverview />} />
        <Route path="/profile" element={<ProfileHealth />} />
        <Route path="/posture" element={<PostureStudio />} />
        <Route path="/workout" element={<WorkoutEngine />} />
        <Route path="/coach" element={<CoachChat />} />
        <Route path="/progress" element={<ProgressAnalytics />} />
      </Route>

      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Toaster
          position="top-right"
          toastOptions={{
            style: {
              background: "#1E1E2E",
              color: "#F5F5F5",
              border: "1px solid #2A2A3E",
              fontSize: "14px",
            },
            success: { iconTheme: { primary: "#00D4AA", secondary: "#1E1E2E" } },
            error:   { iconTheme: { primary: "#FF4757", secondary: "#1E1E2E" } },
          }}
        />
        <AppRoutes />
      </AuthProvider>
    </BrowserRouter>
  );
}
